import {DUAL_GUIDE_TEXT} from './guide-dual-text.js';
import {RULES,BODY_LIMITS} from './model-rules.js';
import {ACTION_DURATIONS,SUBSTEPS,DT} from './action-timing.js';
import {STRUCTURAL_DEFAULTS,STRUCTURE_RULES as S} from './brain-structure-rules.js';
import {initialConnectionBudget,initialLayerCounts} from './brain-initialization.js';
